package com.gamagerecruiters.marketplace.modules.notification.domain;
import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import org.junit.jupiter.api.Test;
class NotificationTypeTest {
    @Test void hasFortyThreeValuesWithoutDuplicates() {
        List<String> expected = List.of("BOOKING_REQUEST_RECEIVED","BOOKING_WITHDRAWN","BOOKING_AUTO_DECLINED","BOOKING_ACCEPTED","BOOKING_DECLINED","BOOKING_EXPIRED","BOOKING_CONFIRMED","BOOKING_CANCELLED","BOOKING_RESPONSE_REMINDER","RESCHEDULE_REQUESTED","RESCHEDULE_APPROVED","RESCHEDULE_REJECTED","RESCHEDULE_EXPIRED","CANCELLATION_PENALTY_APPLIED","PAYMENT_SUCCESSFUL","PAYMENT_FAILED","REFUND_PROCESSED","EARNINGS_AVAILABLE","PAYOUT_REQUESTED","PAYOUT_PAID","PAYOUT_FAILED","PAYOUT_ON_HOLD","PROVIDER_PENALTY_RECORDED","COMPLETION_CONFIRM_REMINDER","PROVIDER_COMPLETE_REMINDER","BOOKING_NOT_STARTED_REMINDER","REVIEW_INVITATION","VERIFICATION_APPROVED","VERIFICATION_REJECTED","VERIFICATION_RESUBMISSION_REQUESTED","VERIFICATION_EXPIRED","DISPUTE_OPENED","DISPUTE_OUTCOME","REVIEW_REMOVED","REVIEW_RESTORED","REVIEW_PUBLISHED","NEW_MESSAGE","SERVICE_COMPLETED_AWAITING_CONFIRMATION","COMPLETION_CONFIRMED","ISSUE_RAISED","NO_SHOW_REPORTED","REVIEW_RECEIVED","REVIEW_REPLY_POSTED");
        List<String> actual = java.util.Arrays.stream(NotificationType.values()).map(Enum::name).toList();
        assertEquals(43, actual.size());
        assertEquals(expected, actual);
        assertEquals(actual.size(), new java.util.HashSet<>(actual).size());
    }
}
